INSERT INTO `project_locations` VALUES (1,1,1,1,'exhibit','반가사유상, 미소의 의미는 ?',NULL,NULL,NULL,'반가사유상(半跏思惟像)은 왼쪽 다리는 내리고 오른쪽 다리는 그 위에 올려 가부좌를 하는 반가부좌 자세로 대좌 위에 앉아 오른손으로 얼굴을 괸 채 명상하는 보살의 모습을 표현한 불상이다.[1] 국립중앙박물관이 \"사유의 방\"에서 전시하고 있는 삼국시대의 금동미륵보살반가사유상 (국보 제78호)과 금동미륵보살반가상 (국보 83호)이 유명하다','C:\\proj\\tracker\\uploads\\location-icons\\1780539259770_ë°ê°ì¬ì_ì.jpg',0,0,'2026-06-04 11:14:19','2026-06-05 16:19:03'),(2,1,2,2,'exhibit','이것은 말인가? 기린인가?',NULL,NULL,NULL,'2026년 5월 29일 · 경주 천마총 장니 천마도 ... 경주 천마총 장니 천마도 (慶州 天馬塚 障泥 天馬圖)는 말의 안장 양쪽에 달아 늘어뜨리는 장니에 그려진 말 (천마) 그림이다.','C:\\proj\\tracker\\uploads\\location-icons\\1780539274804_ì²ë§ì´.jpg',0,0,'2026-06-04 11:14:34','2026-06-05 16:03:57'),(3,1,3,3,'exhibit','왜 금관이었나 ?',NULL,NULL,NULL,'좁은 의미로는 순금 금관을 말하지만, 편의상 금동관, 은관 등 다른 금속으로 만든 유사한 형식의 관도 같이 금관이라고 통칭하기도 한다. 금으로 도금하거나 금박을 입히기도 한 청동금동관은 특히 한반도 남부 옛 마한 권역, 가야, 신라에서 많이 출토되는데 대체로 금제 관보다는 계급이 낮은 인물이나 지방세력의 지도자급이 사용한 듯하다. 흔히 왕관으로만 알려졌지만, 실제로는 왕뿐만 아니라 고위 귀족층도 착용한 듯하다.','C:\\proj\\tracker\\uploads\\location-icons\\1780574458623_ê¸ê´.jpg',0,0,'2026-06-04 21:00:58','2026-06-05 09:25:43'),(4,3,1,1,'exhibit','맹호',NULL,NULL,NULL,'\'범(호랑이)\' 그림은 조선 후기 회화의 백미로 꼽힙니다. 대표작인 〈송하맹호도(松下猛虎圖)〉는 극사실적인 세밀함과 호랑이의 용맹함을 완벽하게 담아낸 세계적인 명작으로 평가받습니다','C:\\proj\\tracker\\uploads\\location-icons\\1780810353977_ê¹íë_02.jpg',0,0,'2026-06-07 14:30:15','2026-06-07 14:32:34'),(5,3,2,2,'exhibit','씨름도',NULL,NULL,NULL,'씨름은 한국 고유의 문화이자 운동 또는 격투기로, 두 사람이 샅바나 바지 허리춤을 잡고 힘과 기예를 겨루어 상대방을 넘어뜨리는 경기이다. 여러 씨름으로 추정되는 그림들 중에 고고학적으로 씨름에 관한 정확한 기원과 모습은 오직 고구려 벽화에서만 볼 수 있다. 세계 각지에도 씨름과 유사한 운동이 있으나 룰과 형태는 매우 다르다. 씨름과 유사한 격투기로는 일본의 스모, 몽골의 부흐, 터키의 씨름 등이 있다.','C:\\proj\\tracker\\uploads\\location-icons\\1780810278355_ê¹íë_01.jpg',0,0,'2026-06-07 14:31:19','2026-06-07 14:56:38'),(6,3,3,3,'exhibit','인왕제색도',NULL,NULL,NULL,'제목의 제색(霽色)이란 단어는 비 갤 제(霽) 자를 사용해서 비가 갠 뒤 하늘의 빛깔이나 풍경을 가리킨다','C:\\proj\\tracker\\uploads\\location-icons\\1780810479333_ê¹íë_03.jpg',0,0,'2026-06-07 14:34:39','2026-06-07 14:56:02'),(7,2,1,1,'location','성심당 롯데백화점 대전점',36.34036530,127.39017640,'google','성심당 롯데백화점 대전점에서 방문 QR코드를 촬영해 주세요','C:\\proj\\tracker\\uploads\\location-icons\\1780966162733_ì±ì¬ë¹ë³¸ì_.jpg',0,0,'2026-06-09 09:33:48','2026-06-09 10:11:23'),(8,2,2,2,'location','한화생명 이글스파크',36.31707890,127.42913450,'google','숨어있는 QR코드를 찾아보세요.\r\n[hint]정문 앞 가로등','C:\\proj\\tracker\\uploads\\location-icons\\1780967792147_ííì´ê¸ì¤íí¬.jpg',0,0,'2026-06-09 09:34:59','2026-06-09 10:16:32'),(9,2,3,3,'location','대전엑스포 시민광장',36.36823540,127.38801520,'google','숨어있는 QR코드를 찾아요',NULL,0,0,'2026-06-09 09:35:53','2026-06-09 10:11:23'),(10,6,1,1,'location','방콕 왕궁',13.74985580,100.49157650,'google','출입구에 있는 QR코드를 찍어주세요. 또는 Roampay로 출입증 구매하면 인증됩니다.','C:\\proj\\tracker\\uploads\\location-icons\\1781511872377_ë°©ì½ìê¶.png',0,1,'2026-06-15 17:07:42','2026-06-15 18:25:13'),(11,6,2,2,'location','프라 쑤멘 요새',13.76397760,100.49569750,'google','입구에서 QR코드를 찍어주세요','C:\\proj\\tracker\\uploads\\location-icons\\1781511904727_íë¼ì¤ììì.png',0,1,'2026-06-15 17:08:55','2026-06-15 18:38:50'),(12,6,3,3,'location','므엉 보란 (고대 도시)',13.53860260,100.62257410,'google','출입구에서 QR코드를 찍어주세요','C:\\proj\\tracker\\uploads\\location-icons\\1781511935108_íë¼ì¤ììì.png',0,1,'2026-06-15 17:10:26','2026-06-15 18:45:36'),(13,6,4,1,'location','Greate palace',13.74985580,100.49157650,'google','현장에서 QR코드릴 찍거나 Roampay로 결제하면 방문으로 인정','C:\\proj\\tracker\\uploads\\location-icons\\1781515686049_ë°©ì½ìê¶.png',0,0,'2026-06-15 18:28:06','2026-06-15 18:28:06'),(14,6,5,2,'location','프라_쑤멘_요새',13.76397760,100.49569750,'google','1번부스앞에서 QR인증 받으세요','C:\\proj\\tracker\\uploads\\location-icons\\1781516682909_íë¼ì¤ììì.png',0,0,'2026-06-15 18:44:43','2026-06-15 18:44:43'),(15,6,6,3,'location','므엉 보란 (고대 도시)',13.53860260,100.62257410,'google','','C:\\proj\\tracker\\uploads\\location-icons\\1781516824490_ë¯ëë¸ëê³_ëëì.jpg',0,0,'2026-06-15 18:47:04','2026-06-15 18:47:04');
