INSERT INTO `project_notices` VALUES (1,2,'행사장 주차 안내','행사 기간 중 컨벤션센터 지하주차장을 이용하실 수 있습니다.\n주차 공간이 한정되어 있으니 가급적 대중교통을 이용해 주세요.',1,0,'active','2026-06-12 08:59:47','2026-06-12 08:59:47'),(2,2,'사전예약 혜택 안내','사전예약하신 방문객께는 현장에서 기념품을 드립니다. 마이페이지의 QR을 제시해 주세요.',0,1,'active','2026-06-12 08:59:47','2026-06-12 09:31:07');
